PHLWINDOW CWindow::create(UP<IWindowBackend> backend) {
    if (!backend)
        return nullptr;

    PHLWINDOW pWindow = SP<CWindow>(new CWindow(std::move(backend)));

    pWindow->m_self = pWindow;
    pWindow->m_backend->attach(pWindow);
    pWindow->initialize();
    pWindow->attachBackendListeners();

    return pWindow;
}

void CWindow::attachBackendListeners() {
    m_backendListeners.map               = m_backend->m_events.map.listen([this] { mapWindow(); });
    m_backendListeners.unmap             = m_backend->m_events.unmap.listen([this] { unmapWindow(); });
    m_backendListeners.commit            = m_backend->m_events.commit.listen([this](bool initial) { commitWindow(initial); });
    m_backendListeners.destroy           = m_backend->m_events.destroy.listen([this] { destroyWindow(); });
    m_backendListeners.surfaceChanged    = m_backend->m_events.surfaceChanged.listen([this](const auto& surface) { onSurfaceChanged(surface); });
    m_backendListeners.metadataChanged   = m_backend->m_events.metadataChanged.listen([this](const auto& metadata) { onUpdateMeta(metadata); });
    m_backendListeners.stateRequest      = m_backend->m_events.stateRequest.listen([this](const auto& request) { onUpdateState(request); });
    m_backendListeners.configureRequest  = m_backend->m_events.configureRequest.listen([this](const auto& box) { onConfigureRequest(box); });
    m_backendListeners.geometryChanged   = m_backend->m_events.geometryChanged.listen([this](const auto& box) { onGeometryChanged(box); });
    m_backendListeners.activationRequest = m_backend->m_events.activationRequest.listen([this] { onActivationRequest(); });
    m_backendListeners.moveRequest       = m_backend->m_events.moveRequest.listen([this] { onMoveRequest(); });
    m_backendListeners.resizeRequest     = m_backend->m_events.resizeRequest.listen([this](eBackendResizeEdge edge) { onResizeRequest(edge); });

        Desktop::windowState()->raise(m_self.lock());

    Desktop::focusState()->fullWindowFocus(m_self.lock(), FOCUS_REASON_DESKTOP_STATE_CHANGE);
    warpCursor();
}

void CWindow::onUpdateState(const SBackendStateRequest& request) {
    requestClientFullscreen({
        .fullscreen        = request.fullscreen,
        .maximized         = request.maximized,
        .fullscreenMonitor = request.fullscreenMonitor,
        .origin            = SClientFullscreenRequest::ORIGIN_BACKEND,
    });

    if (request.minimized.has_value() && mapped()) {
        const bool MINIMIZED = request.minimized.value();
        IPC::Socket2::sock()->postEvent({.event = "minimized", .data = std::format("{:x},{}", rc<uintptr_t>(this), MINIMIZED ? 1 : 0)});
        Event::bus()->m_events.window.minimize.emit(m_self.lock(), MINIMIZED);
    }
}

void CWindow::requestClientFullscreen(const SClientFullscreenRequest& request) {
    // a client re-asserting fullscreen every frame (notably gamescope) would snap the window back the instant
    // the drag handler pulls it out of fullscreen, so ignore the request while this window is being dragged.

struct SBackendStateRequest {
    std::optional<bool>      fullscreen;
    std::optional<MONITORID> fullscreenMonitor;
    std::optional<bool>      maximized;
    std::optional<bool>      minimized;
};

struct SBackendClientID {
    eBackendType type = eBackendType::WINDOW_BACKEND_WAYLAND;

if (TOPLEVEL) {
    m_listeners.metadata   = TOPLEVEL->m_events.metadataChanged.listen([this] { updateMetadata(true); });
    m_listeners.state      = TOPLEVEL->m_events.stateChanged.listen([this] {
        const auto RESOURCE = m_resource.lock();
        const auto TOPLEVEL = RESOURCE ? RESOURCE->m_toplevel.lock() : nullptr;
        if (!TOPLEVEL)
            return;

        updateTraits(true);

        // This is tricky, but we essentially check if the app requested any type of maximize.
        // If it did, we send the inverse of our internal state.
        // This is because apps are always "maximized" under Hyprland + Wayland, check setMaximized().
        const auto REQUESTED_MAXIMIZE = TOPLEVEL->m_state.requestsMaximize.has_value();
        auto       requestsMaximize   = std::optional<bool>{std::nullopt};
        if (REQUESTED_MAXIMIZE)
            requestsMaximize = !Fullscreen::controller()->isFullscreen(m_window.lock(), Fullscreen::FSMODE_MAXIMIZED);

        m_events.stateRequest.emit({
            .fullscreen        = TOPLEVEL->m_state.requestsFullscreen,
            .fullscreenMonitor = TOPLEVEL->m_state.requestsFullscreenMonitor,
            .maximized         = requestsMaximize,
            .minimized         = TOPLEVEL->m_state.requestsMinimize,
        });
    });
    m_listeners.sizeLimits = TOPLEVEL->m_events.sizeLimitsChanged.listen([this] {

    m_listeners = {};
    m_events.destroy.emit();
});
m_listeners.resourceChange = surface->m_events.resourceChange.listen([this] {
    updateSurface(true);
    updateMetadata(true);
    updateTraits(true);
});
m_listeners.state          = surface->m_events.stateChanged.listen([this] {
    const auto SURFACE = m_xwaylandSurface.lock();
    if (!SURFACE)
        return;

    const SBackendStateRequest REQUEST = {
        .fullscreen = SURFACE->m_state.requestsFullscreen,
        .maximized  = SURFACE->m_state.requestsMaximize,
        .minimized  = SURFACE->m_state.requestsMinimize,
    };

    SURFACE->m_state.requestsFullscreen.reset();
    SURFACE->m_state.requestsMaximize.reset();
    SURFACE->m_state.requestsMinimize.reset();

    updateTraits(true);
    m_events.stateRequest.emit(REQUEST);

    m_state.requestsFullscreen.reset();
});

m_resource->setSetMinimized([this](CXdgToplevel* r) {
    m_state.requestsMinimize = true;
    m_events.stateChanged.emit();
    m_state.requestsMinimize.reset();
});

m_resource->setSetParent([this](CXdgToplevel* r, wl_resource* parentR) {
    auto newp = parentR ? CXDGToplevelResource::fromResource(parentR) : nullptr;
    setNewParent(newp);
});

